"""Twelve database curricula with explicit engines and local practice boundaries."""
import runpy
from pathlib import Path
api=runpy.run_path(str(Path(__file__).with_name('author-web.py')))
L,build=api['lesson'],api['build']

build('postgresql',
 'PostgreSQL stores related data in tables and provides SQL tools for asking questions. Learn a small book table, safe changes and a few PostgreSQL features such as JSONB and useful returned values.',
 'Use PostgreSQL in a new practice database through psql or a database editor. These are PostgreSQL examples, not SQLite. They do not run in this site\'s SQL playground. Use only sample data.',
 'Uses PostgreSQL 16+ core SQL, identity columns, JSONB and window functions.', [
 L('Ask the database a question', 'A SELECT query can calculate a value without reading a table. An alias gives the answer column a clear name.', 'sql', 'SELECT 2 + 3 AS total_books;', 'The result is one row with total_books equal to 5.', 'PostgreSQL is a separate database tool. The site itself does not connect to it or ask you to log in.', 'Change the two numbers and predict the answer.', 'What does AS total_books do?', 'Names the result column', 'Creates a user account', slug='introduction'),
 L('Make a practice table', 'A table names the facts each row can hold. An identity column can create a new numeric id automatically.', 'sql', 'CREATE TEMP TABLE pg_books (\n id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n title text NOT NULL,\n pages integer CHECK (pages > 0)\n);', 'A temporary book table exists for the current database session. Each new row must have a title and a positive page count.', 'Run the table creation once per session. Temporary tables disappear when that session ends.', 'Explain which rule prevents a negative page count.', 'Which rule requires a title?', 'NOT NULL', 'AS IDENTITY'),
 L('Return an inserted value', 'RETURNING asks PostgreSQL to show values from a row it has just changed. It is useful for reading an automatically made id.', 'sql', '-- After creating pg_books in the previous lesson:\nINSERT INTO pg_books (title,pages) VALUES (\'Moon Trip\',60)\nRETURNING id,title;', 'The inserted row is shown with its generated id and Moon Trip title.', 'Do not guess the next id in a real app. Use the value the database returns.', 'Insert another sample book and inspect its id.', 'What does RETURNING show?', 'Values from the row just inserted', 'Every password on the server'),
 L('Search text without letter case', 'ILIKE is PostgreSQL\'s case-insensitive pattern match. A percent sign matches any length of text.', 'sql', "WITH books(title) AS (VALUES ('Moon Trip'),('Garden Days'))\nSELECT title FROM books WHERE title ILIKE 'moon%';", 'The result contains Moon Trip even though the pattern begins with lowercase moon.', 'ILIKE is not standard in every SQL engine. Use the PostgreSQL tool for this syntax.', 'Change the pattern to garden%.', 'What does the percent sign match?', 'Any following text', 'Only a percent character'),
 L('Sort before taking a few rows', 'ORDER BY chooses the result order. LIMIT then restricts how many of those rows are returned.', 'sql', "WITH books(title,pages) AS (VALUES ('Moon Trip',60),('Garden Days',40),('Tiny Seed',20))\nSELECT title,pages FROM books ORDER BY pages,title LIMIT 2;", 'Tiny Seed appears first, then Garden Days.', 'Without ORDER BY, the database does not promise which rows a LIMIT query returns first.', 'Ask for the two longest books instead.', 'Why sort before LIMIT?', 'To make the chosen first rows meaningful', 'To make all rows have the same page count'),
 L('Count rows in each group', 'GROUP BY puts matching values together. An aggregate such as count gives one answer for each group.', 'sql', "WITH books(kind) AS (VALUES ('story'),('science'),('story'))\nSELECT kind,count(*) AS book_count FROM books GROUP BY kind ORDER BY kind;", 'Science has 1 book and story has 2.', 'Every selected non-aggregate value needs a suitable grouping rule. Do not choose an unrelated title from each group.', 'Add another science row and predict the counts.', 'What does count(*) count?', 'Rows in each group', 'Only letters in the group name'),
 L('Join related facts', 'A join matches rows using a shared value. It can put an author name beside a book title stored in another table.', 'sql', "WITH authors(id,name) AS (VALUES (1,'Mia')),\nbooks(title,author_id) AS (VALUES ('Moon Trip',1))\nSELECT books.title,authors.name FROM books JOIN authors ON authors.id=books.author_id;", 'The row pairs Moon Trip with Mia.', 'Choose the join condition carefully. A missing condition can combine many unrelated rows.', 'Add another author and a matching book.', 'What links the two records?', 'authors.id equals books.author_id', 'Their row positions happen to match'),
 L('Keep a change in a transaction', 'A transaction groups changes into one job. ROLLBACK cancels uncommitted changes so you can practise safely with sample data.', 'sql', "CREATE TEMP TABLE pg_scores (points integer);\nBEGIN;\nINSERT INTO pg_scores VALUES (5);\nROLLBACK;\nSELECT count(*) FROM pg_scores;", 'The final count is 0 because the insert was rolled back.', 'Create this temporary table once. COMMIT would keep the change instead of cancelling it.', 'Explain the difference between COMMIT and ROLLBACK.', 'Why is the final count zero?', 'ROLLBACK undid the insert', 'SELECT deleted the row'),
 L('Read a JSONB field', 'JSONB stores JSON data in a form PostgreSQL can query. The ->> operator reads one field as text.', 'sql', "SELECT '{\"title\":\"Moon Trip\",\"pages\":60}'::jsonb ->> 'title' AS title;", 'The title column contains Moon Trip.', 'JSON fields are not a replacement for every table column. Keep important relationships and rules clear.', 'Read the pages field and notice the text result.', 'What does ->> return for a JSON field?', 'Its text value', 'A complete new database'),
 L('Use an array for a small value list', 'PostgreSQL can store an array of values. ANY can test whether a value matches one item in that array.', 'sql', "SELECT 'science' = ANY(ARRAY['story','science','poetry']) AS allowed;", 'The result is true because science is in the array.', 'An array may suit a small value set, but a related table can be clearer when each item needs its own facts.', 'Test a word that is not in the array.', 'Why is allowed true?', 'science matches an array item', 'ANY makes every comparison true'),
 L('Number rows without grouping them', 'A window function calculates across related rows while keeping each row visible. row_number can number a sorted result.', 'sql', "WITH books(title,pages) AS (VALUES ('Moon Trip',60),('Tiny Seed',20))\nSELECT title,row_number() OVER (ORDER BY pages,title) AS reading_order FROM books ORDER BY reading_order;", 'Tiny Seed gets 1 and Moon Trip gets 2.', 'A window ORDER BY sets the calculation order. Use an outer ORDER BY when the displayed row order matters too.', 'Reverse the window ordering and predict the numbers.', 'Does row_number merge the rows into one group result?', 'No, each row stays visible', 'Yes, it removes every original row'),
 L('Read a query plan first', 'EXPLAIN shows how PostgreSQL plans to run a query. It can help you understand a table scan before guessing which index to add.', 'sql', 'EXPLAIN SELECT * FROM pg_books WHERE id=1;', 'The plan describes a possible access method for the practice table. Exact details depend on its size and statistics.', 'EXPLAIN ANALYZE actually runs the query. Be careful with statements that change data when using that option.', 'Find the scan type in the plan output.', 'What does plain EXPLAIN do?', 'Shows the planned work without executing this SELECT for results', 'Guarantees that an index is always fastest'),
])

build('cassandra',
 'Cassandra stores data across machines and groups rows by a partition key. You design a table around the question you need to ask. Learn a small reading log with CQL and see why its rules differ from ordinary table joins.',
 'Use a local single-node Cassandra 4+ practice cluster and cqlsh. The SimpleStrategy keyspace below is only for that local lesson. These commands do not run in this site\'s SQLite playground.',
 'Uses Cassandra 4+ CQL core features with a clearly limited single-node practice setup.', [
 L('Create a local practice keyspace', 'A keyspace groups Cassandra tables and defines replication. Replication means how many copies of data are kept across nodes.', 'sql', "CREATE KEYSPACE IF NOT EXISTS cma_reading WITH replication = {'class':'SimpleStrategy','replication_factor':1};\nUSE cma_reading;", 'The local practice keyspace uses one replica.', 'SimpleStrategy with one replica is for this local exercise, not a resilient production design. Production needs a reviewed datacenter-aware strategy.', 'Explain what replication_factor 1 means.', 'How many replicas does this practice setup request?', 'One', 'One per browser tab', slug='introduction'),
 L('Design a table for one question', 'The partition key chooses a group of rows stored together. A clustering column orders rows inside that partition.', 'sql', 'CREATE TABLE IF NOT EXISTS reading_by_reader(reader_id text,day date,title text,pages int,PRIMARY KEY((reader_id),day)) WITH CLUSTERING ORDER BY(day DESC);', 'The table groups a reader\'s entries by reader_id and orders that reader\'s days newest first.', 'This schema allows one row per reader per day. Add another key part if multiple entries per day must be distinct.', 'State the question this table can answer efficiently.', 'Which field is the partition key?', 'reader_id', 'pages'),
 L('Insert a reading entry', 'An INSERT writes values at a primary-key address. Writing the same key again updates those supplied values rather than making a duplicate row.', 'sql', "INSERT INTO reading_by_reader(reader_id,day,title,pages) VALUES('mia','2026-11-16','Moon Trip',20);", 'Mia\'s entry for that day stores Moon Trip and 20 pages.', 'Know the full primary key. Reusing it can overwrite values at the same record address.', 'Insert a different day for the same reader.', 'What identifies this row uniquely?', 'reader_id together with day', 'The title alone'),
 L('Read one partition', 'A Cassandra query is efficient when it names the partition key. It can then read the rows grouped under that key.', 'sql', "SELECT day,title,pages FROM reading_by_reader WHERE reader_id='mia';", 'The query returns Mia\'s stored days in the table\'s clustering order.', 'Do not expect arbitrary joins and filters to work like PostgreSQL. Model tables for the reads you need.', 'Read a different sample reader id.', 'Which condition lets this query choose a partition?', 'reader_id equals mia', 'pages is any number'),
 L('Read a range inside a partition', 'After choosing a partition, a query can use a range on its clustering column. This is useful for a reader\'s recent days.', 'sql', "SELECT day,title FROM reading_by_reader WHERE reader_id='mia' AND day>='2026-11-01' LIMIT 5;", 'At most five of Mia\'s entries from the chosen date range are returned.', 'A range rule on a different non-key column may need a different table design. Do not add ALLOW FILTERING as a reflex.', 'Change the start date and predict which sample days match.', 'What column supplies this range?', 'The clustering day column', 'An unrelated browser setting'),
 L('Keep partitions a manageable size', 'A partition should not grow without a useful bound. A time bucket can split a long history into smaller groups.', 'sql', 'CREATE TABLE IF NOT EXISTS reading_by_month(reader_id text,month text,day date,title text,PRIMARY KEY((reader_id,month),day));', 'The partition key now combines a reader and a month, such as mia with 2026-11.', 'The right bucket depends on real data size and queries. A month label is a modelling choice, not an automatic Cassandra feature.', 'Name the partition values for Mia in November 2026.', 'Why add month to this partition key?', 'To split an unbounded history into smaller groups', 'To sort all readers alphabetically on one node'),
 L('Expire temporary fields', 'A TTL gives written values a time to live. Cassandra removes them from ordinary reads after they expire.', 'sql', "INSERT INTO reading_by_reader(reader_id,day,title,pages) VALUES('temporary-reader','2026-11-16','Practice',1) USING TTL 60;\nSELECT TTL(title) FROM reading_by_reader WHERE reader_id='temporary-reader' AND day='2026-11-16';", 'The TTL value is near 60 seconds when read immediately and decreases with time.', 'Expiration creates deletion work that is cleaned up later. A TTL is not a free way to ignore data-lifecycle planning.', 'Read the TTL twice a few seconds apart.', 'What unit is USING TTL 60 measured in?', 'Seconds', 'Days'),
 L('Update by the full key', 'An UPDATE names the row through its key and changes selected values. Cassandra writes can create missing non-key values at that address.', 'sql', "UPDATE reading_by_reader SET pages=25 WHERE reader_id='mia' AND day='2026-11-16';", 'The page count at that exact reader-and-day address becomes 25.', 'Do not assume UPDATE proves the old row existed. If that matters, learn conditional writes and their cost.', 'Read the same key after the update.', 'Why include both key parts in the WHERE clause?', 'To identify the exact row to update', 'To make a title become a primary key'),
 L('Delete one known row', 'A DELETE marks selected data as deleted. Cassandra uses tombstones so replicas can learn that a value was removed.', 'sql', "DELETE FROM reading_by_reader WHERE reader_id='temporary-reader' AND day='2026-11-16';", 'The named temporary sample entry is no longer returned by normal reads.', 'Delete only intended keys. Large tombstone-heavy reads can become expensive, so design retention carefully.', 'Explain why the delete names both key fields.', 'What is a tombstone used for?', 'Representing a deletion across replicas', 'Drawing a chart border'),
 L('Group a small related write', 'A batch can group related mutations. It is not a general speed trick for sending many unrelated partitions at once.', 'sql', "BEGIN BATCH\nUPDATE reading_by_reader SET pages=21 WHERE reader_id='mia' AND day='2026-11-16';\nUPDATE reading_by_reader SET title='Moon Trip, chapter 2' WHERE reader_id='mia' AND day='2026-11-16';\nAPPLY BATCH;", 'Both changes target the same practice row in one partition.', 'Avoid huge cross-partition batches as a bulk-loading shortcut. Their coordination can add work.', 'Identify why both updates target the same partition.', 'Is a large unrelated batch automatically faster?', 'No, it can add coordination cost', 'Yes, more partitions always make it faster'),
 L('Use a dedicated counter table', 'Cassandra counters use a special column type and update rules. Keep them in a table designed for counts.', 'sql', "CREATE TABLE IF NOT EXISTS books_count(reader_id text PRIMARY KEY,total counter);\nUPDATE books_count SET total=total+1 WHERE reader_id='mia';\nSELECT total FROM books_count WHERE reader_id='mia';", 'The stored counter increases by one each time the update is applied.', 'Counter retries need care because repeating an increment can count twice. Counter columns also have special schema restrictions.', 'Explain what happens if the same increment is retried twice.', 'Does repeating this counter update leave the value unchanged?', 'No, it can increment again', 'Yes, every counter update is idempotent'),
 L('Match consistency to the cluster', 'A consistency level tells Cassandra how many replicas must answer an operation. It only makes sense together with the replication setup.', 'text', 'Worked example with three replicas:\nONE needs one replica response.\nQUORUM needs a majority: two responses.\nThe local course has only one replica, so it cannot demonstrate surviving multiple replica failures.', 'The example shows why a stronger response requirement can trade availability for stronger agreement.', 'Do not choose a production consistency policy from a one-node demo alone. Test failures with the actual replication layout.', 'Calculate the majority of three replicas.', 'How many responses form a quorum of three?', 'Two', 'All three are always required'),
])

build('neo4j',
 'Neo4j stores a graph: things are nodes, and connections are relationships. Its query language is Cypher. Learn a small graph of readers and books, then ask questions by following named connections.',
 'Use Neo4j 5+ locally with Neo4j Browser or another Cypher editor. These queries use fictional cma-prefixed ids. Cypher is not SQL and does not run in this site\'s SQL playground.',
 'Uses Neo4j 5+ Cypher labels, relationships, constraints and core matching clauses.', [
 L('Create a node with a label', 'A node represents one thing. A label says what kind of thing it is, and properties hold its named facts.', 'cypher', "CREATE (b:Book {id:'cma-b1',title:'Moon Trip',pages:60}) RETURN b.title;", 'A Book node is created and Moon Trip is returned.', 'CREATE always creates a new node. Repeating it can create duplicates unless a suitable constraint stops it.', 'Identify the label and two properties in the example.', 'What is Book in this pattern?', 'A node label', 'A relationship direction', slug='introduction'),
 L('Find a node by a property', 'MATCH finds graph patterns. A property condition can choose the node with a known id.', 'cypher', "MATCH (b:Book {id:'cma-b1'}) RETURN b.title,b.pages;", 'The previously created book returns its title and 60 pages.', 'A label plus id property is clearer than depending on an internal database id for application identity.', 'Return only the title from this match.', 'Which clause finds existing graph patterns?', 'MATCH', 'CREATE every time'),
 L('Add a uniqueness rule', 'A uniqueness constraint prevents two nodes with a label from sharing the same chosen property value.', 'cypher', 'CREATE CONSTRAINT cma_book_id IF NOT EXISTS FOR (b:Book) REQUIRE b.id IS UNIQUE;', 'Neo4j creates the constraint if the existing Book ids satisfy it.', 'Existing duplicate ids can make this fail. Inspect practice data and create the constraint before repeated inserts when possible.', 'Explain why a stable unique book id is useful.', 'What does this constraint make unique?', 'Book.id values', 'Every word in every title'),
 L('Match or create with MERGE', 'MERGE finds a pattern or creates it if missing. Merge on a stable key, then SET fields that may change.', 'cypher', "MERGE (b:Book {id:'cma-b2'}) SET b.title='Garden Days',b.pages=40 RETURN b.title;", 'The book with id cma-b2 is created or updated with the title Garden Days.', 'Putting a changing title into the MERGE key pattern can create unintended new nodes. Keep identity separate from changing facts.', 'Run the query twice and check the number of matching ids.', 'Why merge on id and then set title?', 'The id is stable while the title may change', 'SET creates a new label every time'),
 L('Connect a reader to a book', 'A relationship gives two nodes a named connection and direction. Its type explains what that connection means.', 'cypher', "MERGE (r:Reader {id:'cma-r1'}) SET r.name='Mia'\nWITH r MATCH (b:Book {id:'cma-b1'}) MERGE (r)-[:READ]->(b) RETURN r.name,b.title;", 'Mia is connected to Moon Trip by an outgoing READ relationship.', 'Use a relationship type that describes the connection. Direction affects how a later pattern matches it.', 'Identify the start and end nodes of READ.', 'What does (r)-[:READ]->(b) mean?', 'The reader has a READ relationship to the book', 'The book is a text field inside the reader'),
 L('Follow a relationship', 'A pattern can follow a known relationship to related nodes. This is how a graph answers connection questions.', 'cypher', "MATCH (r:Reader {id:'cma-r1'})-[:READ]->(b:Book) RETURN r.name,b.title;", 'The result lists the books connected to Mia through READ.', 'A reversed arrow asks a different pattern. Match the direction used by your model.', 'Compare this pattern with a reversed arrow.', 'What information is being followed?', 'The READ connections from the reader', 'The row order in a table'),
 L('Filter nodes with WHERE', 'WHERE adds a condition to a matched pattern. It can filter a numeric property such as page count.', 'cypher', 'MATCH (b:Book) WHERE b.id STARTS WITH "cma-" AND b.pages>=50 RETURN b.title,b.pages;', 'The sample 60-page Moon Trip matches, while the 40-page Garden Days does not.', 'Use the practice-id prefix so this exercise does not accidentally include unrelated graph data.', 'Change the minimum to 30.', 'Which book passes the 50-page rule?', 'Moon Trip with 60 pages', 'Garden Days with 40 pages'),
 L('Sort and limit graph results', 'ORDER BY sorts returned rows from a graph query. LIMIT keeps only the chosen number.', 'cypher', "MATCH (b:Book) WHERE b.id STARTS WITH 'cma-' RETURN b.title,b.pages ORDER BY b.pages,b.title LIMIT 1;", 'With the two sample books, Garden Days is the shortest result.', 'The graph model does not give results a useful default order. State the order when it matters.', 'Return the longest sample book instead.', 'Why add ORDER BY before LIMIT?', 'To define which result is first', 'To add a new relationship'),
 L('Count connected books', 'An aggregate can summarise matched relationships. COUNT counts the matched book values in each group.', 'cypher', "MATCH (r:Reader {id:'cma-r1'})-[:READ]->(b:Book) RETURN r.name,count(b) AS books_read;", 'Mia has one matched book in the seeded graph.', 'Multiple matching relationships can affect counts. Use count(DISTINCT b) when you need unique books.', 'Explain when DISTINCT would matter.', 'What does count(DISTINCT b) avoid?', 'Counting the same matched book more than once', 'Reading every book property at all'),
 L('Keep a reader with no match', 'OPTIONAL MATCH keeps the earlier row even when the optional connection is missing. Missing values appear as null.', 'cypher', "MERGE (r:Reader {id:'cma-r2'}) SET r.name='Sam'\nWITH r OPTIONAL MATCH (r)-[:READ]->(b:Book) RETURN r.name,b.title;", 'Sam is returned with a null book title if no READ relationship exists.', 'A regular MATCH would remove the row when the pattern has no match. Choose based on the question you need to answer.', 'Explain why Sam should still appear in a list of all readers.', 'What does OPTIONAL MATCH preserve?', 'The earlier row even without a matching optional relationship', 'Only rows that have every possible relationship'),
 L('Change a relationship fact', 'Relationships can hold properties too. A property can describe the connection itself, such as when a reader finished a book.', 'cypher', "MATCH (:Reader {id:'cma-r1'})-[read:READ]->(:Book {id:'cma-b1'})\nSET read.finishedOn=date('2026-11-16') RETURN read.finishedOn;", 'The READ relationship receives the finish date.', 'Store a fact on the thing it describes. A reader-book finish date belongs to that reading connection, not every copy of the book.', 'Name another fact that belongs to a reading relationship.', 'Where is finishedOn stored here?', 'On the READ relationship', 'On every Book node'),
 L('Remove one practice node carefully', 'A connected node cannot be deleted normally while its relationships remain. DETACH DELETE removes that node and its attached relationships.', 'cypher', "MATCH (r:Reader {id:'cma-r2'}) DETACH DELETE r;", 'Only the sample reader cma-r2 and its own connections are removed.', 'Check the match before deleting. DETACH DELETE can remove important links if the pattern is too broad.', 'Run the MATCH as a RETURN first to inspect its target.', 'Why inspect the MATCH before deletion?', 'To confirm the exact node and connections being removed', 'To make deletion reversible automatically'),
])

build('dynamodb',
 'DynamoDB stores items addressed by keys. A partition key groups related items, and a sort key orders them within that group. Learn the request shapes with a local practice table and a small book list.',
 'Use DynamoDB Local and the AWS CLI or SDK in a separate practice project. Point every command at http://localhost:8000. Low-level JSON examples show request bodies; provide them to the matching CLI command or SDK method.',
 'Uses DynamoDB core table/item/query APIs with DynamoDB Local; no real AWS resources are created by this site.', [
 L('Design the item key', 'A partition key chooses an item group. A sort key identifies and orders items within that group. Together they can identify one item.', 'json', '{"reader":{"S":"mia"},"book":{"S":"moon-trip"},"title":{"S":"Moon Trip"},"pages":{"N":"60"}}', 'The low-level item uses reader as the partition key and book as the sort key. N values are represented as strings in this wire format.', 'This typed JSON is the low-level DynamoDB format, not ordinary app JSON. Document clients use a simpler format.', 'Identify both key values in the item.', 'Which pair identifies this sample item?', 'reader and book', 'title and the JSON field order', slug='introduction'),
 L('Create a local keyed table', 'A DynamoDB table declares its key attributes. Other item fields do not need to be declared as table columns.', 'bash', 'aws dynamodb create-table --table-name cma-books --attribute-definitions AttributeName=reader,AttributeType=S AttributeName=book,AttributeType=S --key-schema AttributeName=reader,KeyType=HASH AttributeName=book,KeyType=RANGE --billing-mode PAY_PER_REQUEST --endpoint-url http://localhost:8000', 'DynamoDB Local creates the sample table with reader and book keys.', 'Keep the local endpoint option. Omitting it can target a real configured AWS account instead.', 'Check that the table key names match the item design.', 'Which attributes are declared in this table definition?', 'The key attributes reader and book', 'Every possible item field'),
 L('Write a known item', 'PutItem writes a complete item at its key. A later PutItem with the same key replaces the item unless a condition prevents it.', 'json', '{"TableName":"cma-books","Item":{"reader":{"S":"mia"},"book":{"S":"moon-trip"},"title":{"S":"Moon Trip"},"pages":{"N":"60"}}}', 'Send this to the local put-item operation. The item is stored at Mia\'s moon-trip key.', 'PutItem is a replacement operation. Use UpdateItem when only selected attributes should change.', 'Add a second item with book set to garden-days.', 'What happens to an existing item at the same key?', 'PutItem replaces it unless guarded by a condition', 'It always creates a duplicate key'),
 L('Read an exact key', 'GetItem reads one item by its complete primary key. A missing item gives no Item field in the response.', 'json', '{"TableName":"cma-books","Key":{"reader":{"S":"mia"},"book":{"S":"moon-trip"}},"ConsistentRead":true}', 'The local get-item response contains the written sample item.', 'Provide both key fields for this table. A title alone cannot identify an item by GetItem.', 'Read a nonexistent book key and inspect the empty result.', 'What key information does this GetItem need?', 'Both reader and book', 'Only the pages field'),
 L('Query one partition', 'Query selects one partition key and can return its related items. It is different from scanning the entire table.', 'json', '{"TableName":"cma-books","KeyConditionExpression":"#reader = :reader","ExpressionAttributeNames":{"#reader":"reader"},"ExpressionAttributeValues":{":reader":{"S":"mia"}}}', 'The local query returns items in Mia\'s partition, ordered by their sort keys.', 'A key condition must fit the table or index key. An arbitrary non-key field needs a different design or a filter after reading.', 'Explain why this query does not read every reader partition.', 'What does Query require for this table?', 'A partition-key equality condition', 'Any random field name'),
 L('Use a sort-key prefix', 'A sort key can support a range or prefix inside one partition. begins_with keeps keys that start with the supplied text.', 'json', '{"TableName":"cma-books","KeyConditionExpression":"#reader=:reader AND begins_with(#book,:prefix)","ExpressionAttributeNames":{"#reader":"reader","#book":"book"},"ExpressionAttributeValues":{":reader":{"S":"mia"},":prefix":{"S":"moon"}}}', 'Mia\'s moon-trip item matches the moon prefix.', 'The prefix test is on the sort key after choosing the partition. It is not a full-text title search.', 'Change the prefix to garden.', 'Which field does begins_with test here?', 'The book sort key', 'Every text field in every item'),
 L('Read all result pages', 'A Query response can be only one page of data. LastEvaluatedKey tells the caller where to continue.', 'json', '{"TableName":"cma-books","KeyConditionExpression":"#reader=:reader","ExpressionAttributeNames":{"#reader":"reader"},"ExpressionAttributeValues":{":reader":{"S":"mia"}},"Limit":1}', 'With several sample items, the response may include LastEvaluatedKey. Pass it as ExclusiveStartKey in the next request.', 'Limit is not a promise that you have read the whole partition. Continue until no LastEvaluatedKey remains.', 'Find the continuation key after querying a multi-item partition.', 'When is the full query finished?', 'When there is no LastEvaluatedKey to continue', 'Always after the first response'),
 L('Update one attribute', 'UpdateItem can change selected attributes at a key. Expression names and values keep field names and data separate from the expression.', 'json', '{"TableName":"cma-books","Key":{"reader":{"S":"mia"},"book":{"S":"moon-trip"}},"UpdateExpression":"SET #pages=:pages","ExpressionAttributeNames":{"#pages":"pages"},"ExpressionAttributeValues":{":pages":{"N":"64"}},"ReturnValues":"ALL_NEW"}', 'The local update returns the item with pages changed to 64.', 'UpdateItem can create an item if it is missing. Add an existence condition when an update must require an old item.', 'Add a condition requiring the reader attribute to exist.', 'Why might an existence condition be useful?', 'To stop an update from creating an unintended missing item', 'To sort the whole table by pages'),
 L('Avoid replacing an existing item', 'A conditional put can require that a key does not already exist. The condition is checked as part of the write.', 'json', '{"TableName":"cma-books","Item":{"reader":{"S":"mia"},"book":{"S":"moon-trip"},"title":{"S":"Another title"}},"ConditionExpression":"attribute_not_exists(#reader)","ExpressionAttributeNames":{"#reader":"reader"}}', 'The write fails with a condition error if that exact key already has an item.', 'A condition failure is an expected outcome to handle, not a reason to retry the same forbidden overwrite forever.', 'Try the condition with a genuinely new book key.', 'What protects the old item from replacement?', 'The attribute_not_exists condition', 'The title being a different string'),
 L('Understand filters and read cost', 'A FilterExpression removes items after DynamoDB reads the key-matching data. It does not make that earlier read work disappear.', 'json', '{"TableName":"cma-books","KeyConditionExpression":"#reader=:reader","FilterExpression":"#pages>=:minimum","ExpressionAttributeNames":{"#reader":"reader","#pages":"pages"},"ExpressionAttributeValues":{":reader":{"S":"mia"},":minimum":{"N":"50"}}}', 'Only matching items with pages at least 50 are returned, but the query reads the partition candidates first.', 'A selective filter on a huge partition can still be expensive. Design a suitable key or index for important access patterns.', 'Explain why a filter can return few rows after reading more.', 'When is this filter applied?', 'After key-matching items are read', 'Before any read work as a new key'),
 L('Know that TTL is not an exact timer', 'DynamoDB TTL uses an epoch-seconds attribute for expiry. Deletion happens later in the background, not at an exact second.', 'json', '{"reader":{"S":"temporary"},"book":{"S":"practice"},"expiresAt":{"N":"1800000000"}}', 'This item shape has an expiry field. A real table must enable TTL on that field; DynamoDB Local does not perform the real background TTL deletion service.', 'Do not rely on TTL to hide a value immediately at its expiry time. Applications may need to filter expired values while deletion is pending.', 'Explain why an expiry field alone is not a countdown timer.', 'Does TTL guarantee deletion at the exact expiry second?', 'No, deletion is asynchronous', 'Yes, every item vanishes at that exact instant'),
 L('Remove one sample item', 'DeleteItem targets one full key. A condition can be added when deletion must depend on the current item state.', 'json', '{"TableName":"cma-books","Key":{"reader":{"S":"mia"},"book":{"S":"moon-trip"}},"ReturnValues":"ALL_OLD"}', 'The local delete-item operation removes the specified sample and can return its previous values.', 'Verify the local endpoint and full key before sending a delete. Deleting an item is different from deleting the table.', 'Read the same key after removing the sample.', 'What limits this deletion to one item?', 'The complete primary key', 'The word DELETE anywhere in the title'),
])

def firestore(body,names):
    return 'import {initializeApp} from "firebase/app";\nimport {getFirestore,connectFirestoreEmulator,'+names+'} from "firebase/firestore";\nconst app=initializeApp({projectId:"demo-reading-club"});\nconst db=getFirestore(app);connectFirestoreEmulator(db,"127.0.0.1",8080);\n'+body

build('firestore',
 'Firestore stores records as documents in collections. This course uses the local Firebase emulator to learn reads, changes, queries and rules with fake book data. The learning website itself does not connect to Firebase.',
 'Use the Firebase Emulator Suite with the demo-reading-club project and Firestore on port 8080. Install the firebase JavaScript SDK in a local browser project. Run each full snippet on a fresh page. Keep the sample rules local.',
 'Uses the modular Firebase Web SDK and a demo project connected only to the local Firestore emulator.', [
 L('Meet collections and documents', 'A collection groups documents. Each document has an id and named fields, such as a book title and page count.', 'json', '{"collection":"books","documentId":"moon-trip","fields":{"title":"Moon Trip","pages":60}}', 'This worked model describes the document at books/moon-trip. The wrapper is an explanation, not an SDK write command.', 'Document ids are not the same as a title field. Choose how ids should work before creating related records.', 'Name one more field that could belong to a book.', 'What groups the book documents?', 'The books collection', 'A CSS class', slug='introduction'),
 L('Start a local emulator', 'An emulator imitates the service on your own computer. A demo project id helps keep practice separate from a real cloud project.', 'bash', 'npx firebase-tools init emulators\nnpx firebase-tools emulators:start --only firestore --project demo-reading-club', 'After choosing Firestore during setup, the local emulator starts. Configure its rules file for the sample books collection.', 'Use a demo- project id and the emulator connection in every practice client. Do not deploy permissive learning rules to a real project.', 'Check that the Firestore emulator is listening on port 8080.', 'Why use a demo project and emulator?', 'To practise locally without real cloud data', 'To bypass production security rules'),
 L('Write a named document', 'setDoc writes fields at a document path you choose. Without merge, it replaces the document data at that path.', 'javascript', firestore('await setDoc(doc(db,"books","moon-trip"),{title:"Moon Trip",pages:60});','setDoc,doc'), 'With local rules allowing the sample write, books/moon-trip contains the two fields.', 'Know whether replacing the whole document is intended. Use merge or update when preserving other fields matters.', 'Write a second sample document with a different id.', 'Who chooses the id in this setDoc call?', 'The code, using moon-trip', 'A CSS selector'),
 L('Read one document', 'getDoc reads a document snapshot. Check exists before reading fields, because the requested document may not be there.', 'javascript', firestore('const snapshot=await getDoc(doc(db,"books","moon-trip"));\nconsole.log(snapshot.exists()?snapshot.data().title:"No book at this path");','getDoc,doc'), 'After the write lesson, this prints Moon Trip. A missing document prints the fallback.', 'A document reference is only an address. It does not prove that a document exists at that address.', 'Try reading a sample id you have not created.', 'Why call snapshot.exists()?', 'To check that the requested document exists', 'To create the document automatically'),
 L('Let Firestore choose an id', 'addDoc adds a document to a collection with an automatically made id. The returned reference tells you that new path.', 'javascript', firestore('const reference=await addDoc(collection(db,"books"),{title:"Garden Days",pages:40});\nconsole.log(reference.id);','addDoc,collection'), 'A new local sample document is created, and its generated id is logged.', 'Calling addDoc again makes another document. Use a chosen stable id when repeating a write should update the same record.', 'Compare ids from two separate sample additions.', 'What happens if you call addDoc twice?', 'Two documents are created', 'The second call always overwrites the first'),
 L('Change selected fields', 'updateDoc changes named fields while leaving other fields alone. It expects the target document to already exist.', 'javascript', firestore('await updateDoc(doc(db,"books","moon-trip"),{pages:64});','updateDoc,doc'), 'The existing moon-trip document keeps its title and changes pages to 64.', 'updateDoc fails when the document is missing. Handle that error instead of assuming every path exists.', 'Update the title without changing pages.', 'What happens to fields omitted from this update?', 'They are kept', 'They are all deleted'),
 L('Ask for matching documents', 'A query applies a rule to a collection. getDocs returns snapshots for documents that match that rule.', 'javascript', firestore('const request=query(collection(db,"books"),where("pages",">=",50));\nconst result=await getDocs(request);\nresult.forEach(item=>console.log(item.id,item.data().title));','query,collection,where,getDocs'), 'Only local books with pages at least 50 are returned.', 'Rules are not filters. A query must be allowed by security rules for every possible result it asks for.', 'Change the page threshold and compare the results.', 'What does this where rule keep?', 'Books with pages at least 50', 'Only the first document added'),
 L('Sort and limit a query', 'orderBy sorts query results by a field. limit caps how many documents are returned.', 'javascript', firestore('const request=query(collection(db,"books"),orderBy("pages"),limit(2));\nconst result=await getDocs(request);\nresult.forEach(item=>console.log(item.data().pages));','query,collection,orderBy,limit,getDocs'), 'At most two documents are returned, from the smallest page counts upward.', 'Documents without the ordered field are not included by this orderBy. More complex queries may require an index.', 'Ask for the longest two books with descending order.', 'What does limit(2) restrict?', 'The number of returned documents', 'The number of fields per document'),
 L('Listen for local updates', 'onSnapshot sends the current result and later changes. It returns a cleanup function that stops the listener.', 'javascript', firestore('const stop=onSnapshot(doc(db,"books","moon-trip"),snapshot=>{console.log(snapshot.exists()?snapshot.data():"Missing");},error=>console.log("Could not listen:",error.code));\n// Call stop() when this page part is removed.','onSnapshot,doc'), 'The callback receives the current document and later allowed updates while listening.', 'Stop listeners you no longer need. A production listener can use network traffic and billed reads.', 'Change the document in the emulator and observe the callback.', 'What does the returned stop function do?', 'Unsubscribes the listener', 'Deletes the document'),
 L('Group writes in a batch', 'A write batch applies several writes together. Either the batch is accepted as a unit or it fails.', 'javascript', firestore('const batch=writeBatch(db);\nbatch.set(doc(db,"books","seed-story"),{title:"Seed Story",pages:20});\nbatch.set(doc(db,"books","rain-story"),{title:"Rain Story",pages:24});\nawait batch.commit();','writeBatch,doc'), 'Both local sample books are written together when the rules allow both writes.', 'A batch does not read values first. Use a transaction for changes that depend on a value read from the database.', 'Explain why both writes need to pass their rules.', 'When is a transaction more suitable than a simple batch?', 'When the write depends on a database value you must read', 'When two fixed sample records are written'),
 L('Keep local practice rules narrow', 'Security rules decide which client reads and writes are allowed. Even a local exercise should name its intended collection and validate important fields.', 'text', 'rules_version = \'2\';\nservice cloud.firestore {\n match /databases/{database}/documents {\n  match /books/{bookId} {\n   allow read: if true;\n   allow create, update: if request.resource.data.keys().hasOnly([\'title\',\'pages\']) && request.resource.data.title is string && request.resource.data.pages is int && request.resource.data.pages > 0;\n   allow delete: if false;\n  }\n }\n}', 'In the emulator, anyone using this demo client can read the books and write valid sample fields. Other collection access remains denied.', 'These are deliberately public local practice rules, not private-user production rules. Never deploy them as protection for private records.', 'Try an invalid negative page count and confirm it is rejected.', 'Do these public demo rules protect private user records?', 'No, they are only for the local public sample', 'Yes, all records become private automatically'),
 L('Treat stored data as input', 'A database record can have a shape your UI does not expect. Check values before using them, even when a type annotation looks reassuring.', 'javascript', 'function bookLabel(data){\n if(!data || typeof data.title!=="string" || typeof data.pages!=="number")return "Book data is incomplete";\n return `${data.title}: ${data.pages} pages`;\n}\nconsole.log(bookLabel({title:"Moon Trip",pages:60}));\nconsole.log(bookLabel({title:"Missing pages"}));', 'The first line describes the book, and the second gives an incomplete-data message.', 'A TypeScript type does not check network data at runtime by itself. Validate important fields.', 'Test a record whose pages field is text.', 'Why check a record\'s fields?', 'Stored or received data may not match the expected shape', 'It creates a second cloud database'),
])

build('supabase',
 'Supabase puts useful app tools around PostgreSQL. This starter course uses a local Supabase project and a public sample book list. Learn tables, read permissions and clear client queries without adding a login to this website.',
 'Use the Supabase local CLI with its required container runtime, then run supabase init and supabase start in a practice project. Use the local URL and public key reported by its status command. SQL runs in the local database tools.',
 'Uses Supabase JavaScript client v2, local PostgreSQL and row-level security for a public read-only book list.', [
 L('Know the database and the client', 'Supabase stores table data in PostgreSQL and exposes APIs around it. A browser client asks those APIs for allowed data.', 'text', 'Browser page -> Supabase API -> PostgreSQL table\nThe public client key identifies the project.\nRow-level security decides which rows the client role may access.', 'The worked flow separates the browser request from the database permission check.', 'A public project key is not a substitute for row-level security. Never place a service-role or secret key in browser code.', 'Point to where row permissions are checked in the flow.', 'What protects allowed row access?', 'Database permissions and row-level security', 'Hiding a public key in JavaScript', slug='introduction'),
 L('Create a local sample table', 'A PostgreSQL table defines the fields used by the API. A primary key gives each record a stable id.', 'sql', 'CREATE TABLE public.cma_books(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,title text NOT NULL,pages integer CHECK(pages>0));', 'The local database has an empty sample table for books.', 'Run this once in the local practice project. Do not create or alter real application tables for the exercise.', 'Explain which rule protects a positive page count.', 'Which field is the primary key?', 'id', 'The displayed row position'),
 L('Seed public sample records', 'Seed data is a small set of known records used for learning or testing. It makes query results easy to check.', 'sql', "INSERT INTO public.cma_books(title,pages) VALUES('Moon Trip',60),('Garden Days',40),('Tiny Seed',20);", 'The three sample records are inserted through the local database tool.', 'Use only fictional public sample data in this course. Inserting from an owner tool is different from allowing browser writes.', 'Count the expected rows after this insert.', 'Why use known seed records?', 'Their expected query answers are easy to verify', 'They make all security rules unnecessary'),
 L('Enable row-level security', 'Row-level security adds a database check for rows accessed through client roles. With it enabled and no suitable policy, ordinary client access is denied.', 'sql', 'ALTER TABLE public.cma_books ENABLE ROW LEVEL SECURITY;', 'The table now uses row-level security. The public client still needs an explicit read policy.', 'Do not disable RLS just to make a browser error disappear. Define the intended policy.', 'Explain why the client may see no rows before a read policy exists.', 'What is needed after enabling RLS for a public read?', 'A suitable SELECT policy', 'A hidden CSS class'),
 L('Allow only the public read', 'A SELECT policy can make fictional sample rows readable to the anon role. Separate SQL privileges and RLS both matter.', 'sql', 'GRANT SELECT ON public.cma_books TO anon;\nCREATE POLICY "Read public sample books" ON public.cma_books FOR SELECT TO anon USING (true);', 'The anon client can read these public sample books. This policy does not grant insert, update or delete access.', 'USING(true) makes these rows public. Use it only for content deliberately intended for every visitor.', 'Name the operations this policy does not allow.', 'Does this SELECT policy permit browser updates?', 'No, it only covers reads', 'Yes, it grants every operation'),
 L('Make a local client', 'createClient connects the JavaScript SDK to the chosen project API. Use the local project URL and its public client key for this exercise.', 'javascript', 'import {createClient} from "@supabase/supabase-js";\nexport const supabase=createClient("http://127.0.0.1:54321","REPLACE_WITH_LOCAL_PUBLIC_KEY");', 'After replacing the placeholder with the local public key from supabase status, the client can make permitted requests.', 'Never replace the placeholder with a service-role key in browser code. A public key works together with RLS.', 'Find the local public key in your practice project status.', 'Which key belongs in this browser sample?', 'The local public client key', 'A service-role secret key'),
 L('Select named columns', 'A select request can ask only for the columns a page needs. The client returns data and a possible error.', 'javascript', 'import {supabase} from "./client.js";\nconst {data,error}=await supabase.from("cma_books").select("id,title").order("id");\nif(error)console.log("Books could not load");else console.log(data);', 'With the table and policy ready, the result contains the sample ids and titles.', 'Handle error as well as data. Request only fields that the page needs and is allowed to show.', 'Select pages along with the existing fields.', 'What does select("id,title") ask for?', 'Only the id and title columns', 'Every table in the project'),
 L('Filter with a comparison', 'The client can add a filter to a query. gte means greater than or equal to.', 'javascript', 'import {supabase} from "./client.js";\nconst {data,error}=await supabase.from("cma_books").select("title,pages").gte("pages",50);\nconsole.log(error?error.message:data);', 'The sample result includes Moon Trip with 60 pages.', 'Client filters do not replace security rules. RLS must still decide which rows may be read.', 'Change the threshold to 30 and predict the titles.', 'What does gte("pages",50) mean?', 'pages is at least 50', 'pages is exactly five'),
 L('Order and limit the result', 'Ordering and limiting help a page request a small useful set. The ordering rule decides which rows are first.', 'javascript', 'import {supabase} from "./client.js";\nconst {data,error}=await supabase.from("cma_books").select("title,pages").order("pages").limit(2);\nconsole.log(error?error.message:data);', 'Tiny Seed and Garden Days are the two shortest sample books.', 'Use a stable tie-break order when paginating real data with equal values.', 'Reverse the page order to find the longest books.', 'Why order before limiting?', 'To define which two rows are chosen', 'To grant new write permission'),
 L('Count without requesting every row', 'A select can request a count while leaving the row body out. This helps when the page only needs the total.', 'javascript', 'import {supabase} from "./client.js";\nconst {count,error}=await supabase.from("cma_books").select("*",{count:"exact",head:true});\nconsole.log(error?error.message:count);', 'The count is 3 for the seeded sample table visible to this role.', 'An exact count may cost work on large tables. Choose it because the feature needs it, not by habit.', 'Compare the returned count with the seed records.', 'What does head:true avoid returning?', 'The row response body', 'All security checks'),
 L('Expect a denied write', 'A read-only policy should reject browser writes. Testing the denied path confirms that the page cannot change public records accidentally.', 'javascript', 'import {supabase} from "./client.js";\nconst {error}=await supabase.from("cma_books").insert({title:"Not allowed",pages:10});\nconsole.log(error?"Write correctly denied":"Check your permissions");', 'With only the read permissions from this course, the insert is denied.', 'Do not broaden database permissions just to make this deliberate denied-write test pass as a write.', 'Confirm the table still has only its intended sample rows.', 'What is the expected result of this browser insert?', 'A denied write error', 'An automatic bypass of RLS'),
 L('Keep environments separate', 'Local and hosted projects have different addresses and keys. A clear environment setup prevents practice code from changing real data.', 'text', 'Local development: local URL, local public key, fictional sample rows.\nHosted app: its own public URL/key and reviewed policies.\nServer-only operations: secret key kept out of browser bundles.\nBefore running changes: verify which project the client points to.', 'The worked checklist keeps the practice project and a real app from being confused.', 'Environment variables included in a frontend bundle are visible to users. A variable name does not make a secret safe.', 'Identify which values in your local client are public.', 'Can a frontend environment variable safely contain a service secret?', 'No, bundled values can be read by users', 'Yes, its variable name hides it'),
])

build('elasticsearch',
 'Elasticsearch searches documents and summarises their fields. It uses indexes, mappings and JSON requests. Learn a tiny book index, the difference between search and exact filters, and clear result summaries.',
 'Use a local Elasticsearch 8+ instance with Kibana Dev Tools. Paste the HTTP request examples into that console. Use only the cma-books practice index. This website does not connect to an Elasticsearch server.',
 'Uses Elasticsearch 8+ REST request syntax and core search/aggregation features.', [
 L('Meet an index and document', 'An index is a group of searchable documents. A document has named fields, such as title and page count.', 'text', 'PUT cma-books/_doc/1\n{"title":"Moon Trip","kind":"story","pages":60}', 'The practice index receives document 1. The response reports whether it was created or updated.', 'Use a disposable local index. Explicit mappings in the next lesson make field behaviour clearer than relying on guesses.', 'Identify the index name and document id in the path.', 'Which part is the document id?', '1', 'title', slug='introduction'),
 L('Choose field mappings first', 'A mapping tells Elasticsearch how a field should be searched. text is for analysed words, while keyword is for exact values.', 'text', 'PUT cma-books-mapped\n{"mappings":{"properties":{"title":{"type":"text"},"kind":{"type":"keyword"},"pages":{"type":"integer"}}}}', 'A new empty practice index is created with explicit field types.', 'Create this separate index once. A field\'s type cannot simply be changed in place after incompatible data is indexed.', 'Explain why kind is a keyword while title is text.', 'Which mapping suits an exact category name?', 'keyword', 'text for every purpose'),
 L('Index a known sample', 'Indexing stores a document so search can use its fields. A refresh makes recently indexed data visible to search.', 'text', 'PUT cma-books-mapped/_doc/1?refresh=wait_for\n{"title":"Moon Trip","kind":"story","pages":60}', 'The response waits until the new sample can be found by search.', 'Forcing frequent immediate refreshes can hurt throughput. Use refresh=wait_for only when the workflow needs visibility before continuing.', 'Index a second sample document with id 2.', 'What does refresh visibility affect?', 'When search can see the new document', 'Whether the title is stored as a password'),
 L('Read one document by id', 'The document get API reads a specific id. It is different from searching for words across many documents.', 'text', 'GET cma-books-mapped/_doc/1', 'The response includes found:true and the stored source for Moon Trip when the document exists.', 'A missing id has a different response. Handle that case instead of assuming every requested id exists.', 'Request an unused practice id and inspect the result.', 'What is used to choose the document here?', 'Its id', 'A relevance score'),
 L('Search analysed words', 'A match query searches text using the field\'s analyser. It is suited to human words in a text field.', 'text', 'GET cma-books-mapped/_search\n{"query":{"match":{"title":"moon"}}}', 'The Moon Trip sample matches the search word moon.', 'A match query is not always an exact whole-field comparison. Analysis can split and normalise words.', 'Search for trip and compare the result.', 'Which query is suited to analysed title words?', 'match', 'A term query on every text field blindly'),
 L('Filter an exact category', 'A term filter checks an exact indexed value. A keyword field is useful when category spelling should match exactly.', 'text', 'GET cma-books-mapped/_search\n{"query":{"bool":{"filter":[{"term":{"kind":"story"}}]}}}', 'Only documents whose keyword kind is story are selected.', 'Keyword values keep their configured exact form. Do not assume a text field behaves like a keyword.', 'Change the category to science after adding a science sample.', 'Why use keyword for kind?', 'It supports an exact category value', 'It automatically translates every category'),
 L('Filter a numeric range', 'A range query selects numbers between bounds. gte means greater than or equal to, and lte means less than or equal to.', 'text', 'GET cma-books-mapped/_search\n{"query":{"range":{"pages":{"gte":30,"lte":80}}}}', 'The 60-page sample fits this range.', 'Choose a numeric mapping for numeric comparisons. A text page count can behave differently.', 'Change the upper bound to 50.', 'Does a 60-page book fit the range 30 through 80?', 'Yes', 'No'),
 L('Combine search and a filter', 'A bool query can combine word search with exact conditions. The word search can score relevance while filters restrict the allowed set.', 'text', 'GET cma-books-mapped/_search\n{"query":{"bool":{"must":[{"match":{"title":"moon"}}],"filter":[{"term":{"kind":"story"}}]}}}', 'The sample must match the title search and also have kind story.', 'must and filter have different scoring roles. Do not assume every clause adds a relevance score.', 'Add a page-count filter to the query.', 'What must a returned document satisfy?', 'Both the title search and category filter', 'Only whichever rule is easiest'),
 L('Ask for a small ordered result', 'A search request can limit its hit count and sort by a field. Source filtering returns only the fields the page needs.', 'text', 'GET cma-books-mapped/_search\n{"size":2,"sort":[{"pages":"asc"}],"_source":["title","pages"],"query":{"match_all":{}}}', 'At most two shortest sample documents are returned with title and pages in their source.', 'For deep pagination, learn search_after with a stable sort. Large from offsets are not a free way to scan everything.', 'Change the sort to descending pages.', 'What does _source selection limit?', 'The returned source fields', 'The number of server computers'),
 L('Count categories with an aggregation', 'An aggregation summarises matching documents. A terms aggregation groups documents by a keyword value.', 'text', 'GET cma-books-mapped/_search\n{"size":0,"aggs":{"by_kind":{"terms":{"field":"kind"}}}}', 'The response contains category buckets with document counts, without ordinary search hits.', 'Terms aggregation returns a limited set of top buckets by default. Do not assume it always lists every category in a huge index.', 'Add another category and inspect the buckets.', 'What does each bucket count represent?', 'Documents in that category', 'Letters in its category name'),
 L('Update one field', 'The update API can change selected fields of an existing document. Its doc object describes the partial change.', 'text', 'POST cma-books-mapped/_update/1\n{"doc":{"pages":64}}', 'Document 1 keeps its other fields and changes pages to 64.', 'A missing document id needs separate handling. Do not assume a partial update creates every missing record automatically.', 'Read document 1 after the update.', 'What does this update change?', 'Only the supplied pages field', 'The entire index name'),
 L('Delete only the sample record', 'The delete API removes one document by its id. Its scope is much narrower than deleting a whole index.', 'text', 'DELETE cma-books-mapped/_doc/1', 'The named sample document is removed. A later get reports it missing.', 'Check the path before deletion. DELETE cma-books-mapped without /_doc/1 would target the index itself.', 'Identify the exact id being removed.', 'What keeps this delete limited to one record?', 'The /_doc/1 path', 'The HTTP method alone'),
])

build('sqlite',
 'SQLite is a small SQL database that can run inside an app. This site uses SQLite for its SQL playground. Learn tables, filters, joins and safe sample changes with examples that run right in the browser.',
 'Use the SQL Run button for examples marked runnable. They use this site\'s in-browser SQLite database and sample-only table names. A Python example needs Python on your own computer instead.',
 'Uses SQLite 3 core features supported by the bundled sql.js engine.', [
 L('Ask SQLite for an answer', 'SQLite can calculate a value without a table. An alias gives the answer column a useful name.', 'sql', 'SELECT 4 + 3 AS books_read;', 'The result has one column named books_read with value 7.', 'This browser database is for practice. Do not assume it saves data after the run or page closes.', 'Change the two numbers and run the query.', 'What is books_read in this query?', 'The result column name', 'A required login name', slug='introduction', runnable=True),
 L('Create a sample table', 'A table defines named columns for each record. INTEGER PRIMARY KEY is a special SQLite form that can supply integer row ids.', 'sql', 'DROP TABLE IF EXISTS cma_sqlite_books;\nCREATE TABLE cma_sqlite_books(id INTEGER PRIMARY KEY,title TEXT NOT NULL,pages INTEGER);\nINSERT INTO cma_sqlite_books(title,pages) VALUES(\'Moon Trip\',60);\nSELECT id,title,pages FROM cma_sqlite_books;', 'The new sample table contains Moon Trip with id 1 and 60 pages.', 'The DROP line resets only this named sample table. Never copy reset commands onto valuable data.', 'Add a second sample book to the INSERT.', 'Which column form gives this row an integer id?', 'INTEGER PRIMARY KEY', 'TEXT NOT NULL', runnable=True),
 L('Inspect the kind of a value', 'SQLite values have storage classes such as integer, real and text. typeof reports the class of an expression.', 'sql', "SELECT typeof(12) AS whole,typeof(2.5) AS decimal_kind,typeof('12') AS words;", 'The values are integer, real and text.', 'A text value that looks like a number is still text in this expression. SQLite column affinity adds further conversion rules.', 'Compare typeof(5) with typeof(\'5\').', 'What is typeof(\'12\') here?', 'text', 'integer automatically', runnable=True),
 L('Filter a query-only list', 'WHERE chooses rows that pass a rule. A WITH list gives this practice query its own small dataset.', 'sql', "WITH books(title,pages) AS (VALUES('Moon Trip',60),('Tiny Seed',20))\nSELECT title FROM books WHERE pages>=50;", 'Only Moon Trip is returned.', 'Use single quotes around SQL text. A number such as 50 does not need quotes.', 'Change the minimum to 10.', 'Why is Tiny Seed left out?', 'Its page count is below 50', 'Its title contains a space', runnable=True),
 L('Sort and limit the result', 'ORDER BY chooses the result order. LIMIT then keeps only the requested number of rows.', 'sql', "WITH books(title,pages) AS (VALUES('Moon Trip',60),('Tiny Seed',20),('Garden Days',40))\nSELECT title FROM books ORDER BY pages,title LIMIT 2;", 'Tiny Seed and Garden Days are returned in that order.', 'Do not rely on table storage order. Add ORDER BY whenever order matters.', 'Return the two longest books.', 'Which clause chooses the result order?', 'ORDER BY', 'LIMIT alone', runnable=True),
 L('Count a group of rows', 'GROUP BY combines matching categories for a summary. COUNT counts the rows in each category.', 'sql', "WITH books(kind) AS (VALUES('story'),('science'),('story'))\nSELECT kind,count(*) AS total FROM books GROUP BY kind ORDER BY kind;", 'Science has one book, and story has two.', 'A grouped result is different from a list of every original book. Select only useful group facts.', 'Add another story row and predict the total.', 'How many result rows are produced for these two categories?', 'Two', 'Three, one per original row', runnable=True),
 L('Join related records', 'A join matches records using a rule. It can show an author name beside a title without repeating that name in every book record.', 'sql', "WITH authors(id,name) AS (VALUES(1,'Mia')),books(title,author_id) AS (VALUES('Moon Trip',1))\nSELECT books.title,authors.name FROM books JOIN authors ON authors.id=books.author_id;", 'The result pairs Moon Trip with Mia.', 'A missing or wrong join rule can make extra combinations. Check with a tiny dataset first.', 'Add one more matching author and book.', 'What links a book to its author?', 'The matching id values', 'The alphabetic order of titles', runnable=True),
 L('Protect a positive number', 'A CHECK constraint gives a rule for stored data. The database rejects a row when that rule is false.', 'sql', "DROP TABLE IF EXISTS cma_sqlite_scores;\nCREATE TABLE cma_sqlite_scores(points INTEGER NOT NULL CHECK(points>=0));\nINSERT INTO cma_sqlite_scores VALUES(5);\nSELECT points FROM cma_sqlite_scores;", 'The sample value 5 is accepted. A negative points value would fail the check.', 'CHECK alone does not replace NOT NULL when a missing value must also be refused.', 'Explain why both NOT NULL and CHECK are useful.', 'Which rule refuses a negative points value?', 'CHECK(points>=0)', 'The table name', runnable=True),
 L('Turn on foreign-key checks', 'A foreign key links a child record to a parent id. SQLite needs foreign-key checking enabled for a connection to enforce the link.', 'sql', "PRAGMA foreign_keys=ON;\nDROP TABLE IF EXISTS cma_sqlite_loans;\nDROP TABLE IF EXISTS cma_sqlite_readers;\nCREATE TABLE cma_sqlite_readers(id INTEGER PRIMARY KEY);\nCREATE TABLE cma_sqlite_loans(reader_id INTEGER REFERENCES cma_sqlite_readers(id));\nINSERT INTO cma_sqlite_readers VALUES(1);\nINSERT INTO cma_sqlite_loans VALUES(1);\nSELECT reader_id FROM cma_sqlite_loans;", 'The valid child row refers to reader 1. A row referring to a missing parent would be rejected with checks enabled.', 'Set the pragma before starting a transaction. Confirm the setting for each new connection.', 'Explain why reader 2 would not be a valid reference yet.', 'What enables these checks in SQLite?', 'PRAGMA foreign_keys=ON', 'Naming a column reader_id alone', runnable=True),
 L('Undo an unfinished change', 'A transaction can group row changes. ROLLBACK cancels uncommitted work inside that transaction.', 'sql', 'DROP TABLE IF EXISTS cma_sqlite_points;\nCREATE TABLE cma_sqlite_points(points INTEGER);\nBEGIN;\nINSERT INTO cma_sqlite_points VALUES(7);\nROLLBACK;\nSELECT count(*) AS rows_left FROM cma_sqlite_points;', 'The final rows_left value is 0.', 'A rollback cannot undo a change that was already committed in an earlier transaction.', 'Replace ROLLBACK with COMMIT in this disposable sample and compare.', 'Why does the table have no rows at the end?', 'The transaction insert was rolled back', 'COUNT removed the rows', runnable=True),
 L('Inspect a table definition', 'PRAGMA table_info shows facts about a table\'s columns. It can help you check the names and declared types your query needs.', 'sql', 'DROP TABLE IF EXISTS cma_sqlite_notes;\nCREATE TABLE cma_sqlite_notes(id INTEGER PRIMARY KEY,message TEXT NOT NULL);\nPRAGMA table_info(cma_sqlite_notes);', 'The result lists id and message with their types and column flags.', 'This is SQLite-specific inspection syntax. Another database tool may use a different command.', 'Find which output row marks message as required.', 'What does table_info describe?', 'The table\'s columns', 'Every file on the computer', runnable=True),
 L('Bind a value from Python', 'An application should pass a value separately from SQL text. Python\'s SQLite driver binds a value where the question-mark placeholder appears.', 'python', 'import sqlite3\nwith sqlite3.connect(":memory:") as connection:\n    connection.execute("CREATE TABLE books(title TEXT)")\n    connection.execute("INSERT INTO books VALUES (?)", ("Moon Trip",))\n    print(connection.execute("SELECT title FROM books").fetchone()[0])', 'Run with Python 3 to print Moon Trip from a temporary in-memory database.', 'Keep the comma in the one-item tuple. Never join untrusted text into a SQL command instead of binding it.', 'Insert a title containing an apostrophe through the bound value.', 'Why use the ? placeholder?', 'To bind data separately from the SQL command', 'To let the title become executable SQL'),
])

build('mariadb',
 'MariaDB is a table database with many roots shared with MySQL. This course uses its own client and features. Learn a small table, grouped text, safe updates and a practice backup in a separate database.',
 'Use MariaDB 10.11+ with its mariadb client in an empty practice database. These dialect-specific examples do not run in the site\'s SQLite playground. Keep the sample database separate from real records.',
 'Uses MariaDB 10.11+ SQL and the mariadb-dump client.', [
 L('Check your database session', 'A database client sends SQL to the MariaDB server. A session can report the server version and currently selected database.', 'sql', 'SELECT VERSION() AS server_version,DATABASE() AS current_database;', 'The result identifies your MariaDB version and selected database. The database value is NULL if none is selected.', 'MariaDB and MySQL are related but not identical. Check the tool and version before copying a version-specific feature.', 'Read the server name and selected database in the result.', 'What does DATABASE() report?', 'The database selected in this session', 'The browser\'s saved passwords', slug='introduction'),
 L('Create an InnoDB sample table', 'InnoDB is a storage engine that supports transactions and foreign keys. AUTO_INCREMENT supplies an id when a row omits it.', 'sql', 'CREATE TABLE cma_maria_books(id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(80) NOT NULL,pages INT) ENGINE=InnoDB;', 'The practice database now has an empty book table with an automatic id column.', 'Create this table once in the practice database. Table creation is not ordinary rollback-safe row work.', 'Explain why the title column uses NOT NULL.', 'Which engine is chosen explicitly?', 'InnoDB', 'SQLite'),
 L('Insert a row and read its id', 'After an insert in the same connection, LAST_INSERT_ID can report the automatically generated id.', 'sql', "INSERT INTO cma_maria_books(title,pages) VALUES('Moon Trip',60);\nSELECT LAST_INSERT_ID() AS new_book_id;", 'The result is the id generated for that insert in this session.', 'Keep the insert and id read in the same connection. Do not use the largest id from all sessions as a guess.', 'Insert another sample book and read its id.', 'Why use the same connection for LAST_INSERT_ID?', 'It tracks the id for that session\'s insert', 'It reads every user\'s newest row together'),
 L('Search a lowercase form', 'LOWER makes text lowercase for a comparison. LIKE uses a pattern, where percent matches extra text.', 'sql', "SELECT title FROM cma_maria_books WHERE LOWER(title) LIKE 'moon%';", 'The sample Moon Trip row matches the lowercase moon pattern.', 'Collation settings also affect text comparisons. State the intended rule instead of assuming every installation has the same collation.', 'Search for a different beginning of a title.', 'What does LOWER(title) help do here?', 'Compare a lowercase form of the title', 'Change the stored title permanently'),
 L('Take a sorted sample', 'ORDER BY arranges rows before LIMIT chooses a few. This makes a shortest-book query clear.', 'sql', 'SELECT title,pages FROM cma_maria_books ORDER BY pages,title LIMIT 3;', 'The query returns at most three rows with the smallest page counts first.', 'A LIMIT without an order does not promise which rows appear first.', 'Change the ordering to longest books first.', 'What does LIMIT 3 restrict?', 'The number of returned rows', 'The length of every title'),
 L('Join grouped text', 'GROUP_CONCAT joins text values from a group into one string. It can make a short list of names for a report.', 'sql', "WITH books AS (SELECT 'story' AS kind,'Moon Trip' AS title UNION ALL SELECT 'story','Tiny Seed')\nSELECT kind,GROUP_CONCAT(title ORDER BY title SEPARATOR ', ') AS titles FROM books GROUP BY kind;", 'The story group has the text Moon Trip, Tiny Seed.', 'Large concatenated results can be limited by server settings. Do not use one long text list as a replacement for normal related rows.', 'Change the separator to a slash.', 'What does GROUP_CONCAT combine?', 'Text values within a group', 'All database files on disk'),
 L('Use a short recursive query', 'A recursive CTE can use earlier results to make later ones. It needs a stopping rule so it does not repeat forever.', 'sql', 'WITH RECURSIVE numbers(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM numbers WHERE n<4) SELECT n FROM numbers;', 'The query returns 1, 2, 3 and 4.', 'Always understand the stop condition. Recursion limits are a guard, not a replacement for a correct rule.', 'Change the stop value to 5.', 'What stops this recursive example?', 'The n<4 rule', 'The colour of the SQL editor'),
 L('Check JSON text', 'MariaDB can work with JSON text using JSON functions. JSON_VALID checks its shape, and JSON_EXTRACT reads a value.', 'sql', "SELECT JSON_VALID('{\"title\":\"Moon Trip\"}') AS valid_json,JSON_UNQUOTE(JSON_EXTRACT('{\"title\":\"Moon Trip\"}','$.title')) AS title;", 'valid_json is 1 and title is Moon Trip.', 'Do not assume MariaDB JSON storage is identical to another database\'s binary JSON type. Learn the engine\'s rules.', 'Read another field from a small JSON object.', 'What does $.title select?', 'The title field at the JSON root', 'Every table named title'),
 L('Handle a duplicate key deliberately', 'ON DUPLICATE KEY UPDATE changes a row when an insert meets an existing unique key. The matching key decides which row is affected.', 'sql', "CREATE TEMPORARY TABLE cma_maria_scores(name VARCHAR(40) PRIMARY KEY,points INT);\nINSERT INTO cma_maria_scores VALUES('Mia',2);\nINSERT INTO cma_maria_scores VALUES('Mia',5) ON DUPLICATE KEY UPDATE points=5;\nSELECT points FROM cma_maria_scores WHERE name='Mia';", 'Mia\'s points become 5 rather than creating a second row with the same key.', 'Understand every unique key on a real table. A duplicate match can happen on more than the primary key.', 'Explain why only one Mia row remains.', 'Why is the existing row updated?', 'The inserted name duplicates its primary key', 'Every insert always replaces the first row'),
 L('Undo row changes in a transaction', 'A transaction on InnoDB can undo row changes before they are committed. Keep setup DDL outside the transaction you are testing.', 'sql', 'CREATE TEMPORARY TABLE cma_maria_points(points INT) ENGINE=InnoDB;\nSTART TRANSACTION;\nINSERT INTO cma_maria_points VALUES(5);\nROLLBACK;\nSELECT COUNT(*) AS rows_left FROM cma_maria_points;', 'The final count is 0 after the insert is rolled back.', 'Other storage engines can have different transaction support. This sample explicitly uses InnoDB.', 'Compare this disposable example using COMMIT.', 'Which engine feature makes this row rollback possible?', 'Transactional InnoDB storage', 'The length of the table name'),
 L('Inspect the actual table rules', 'SHOW CREATE TABLE prints the database\'s stored definition. It helps you check keys, types and the storage engine instead of guessing.', 'sql', 'SHOW CREATE TABLE cma_maria_books;', 'The result includes the practice table definition as MariaDB stores it.', 'The displayed formatting may differ from your original statement. Read the meaning of the rules.', 'Find AUTO_INCREMENT and the engine in the output.', 'What does SHOW CREATE TABLE show?', 'The stored table definition', 'Every row as a chart'),
 L('Make a practice database backup', 'A logical dump writes SQL that can recreate database objects and rows. Test restoring a backup into a separate empty database.', 'bash', 'mariadb-dump --single-transaction --user=practice_user --password practice_db > practice-backup.sql', 'The client asks for a password and writes a dump of the named practice database to a local file.', 'Do not put a real password directly in the command. A dump can contain private data; use sample records and test restoration separately.', 'Check that your practice dump file was created.', 'What should you do to know a backup is useful?', 'Test restoring it into a separate practice database', 'Only assume a file name means it is correct'),
])

build('redis',
 'Redis stores values under keys and offers useful data structures. It often keeps fast temporary data such as counts and queues. Learn its strings, lists and sets with clearly named practice keys.',
 'Use a local Redis server and redis-cli. Commands here use cma: practice keys only. Redis commands do not run in the site\'s SQLite playground. Do not connect these exercises to a production database.',
 'Uses stable Redis core commands for strings, hashes, collections and transactions.', [
 L('Store a value under a key', 'A key is a name used to find a value. SET stores a string, and GET reads that string back.', 'text', 'SET cma:club "Garden club"\nGET cma:club', 'SET replies OK. GET returns Garden club.', 'A key belongs to this Redis database, not your browser. Use a prefix to keep practice values easy to identify.', 'Store and read another sample club name.', 'What does GET need to find the value?', 'Its key', 'Its text colour', slug='introduction'),
 L('Count with an atomic increment', 'INCR adds one to a key holding an integer. Redis performs that increment as one command.', 'text', 'SET cma:books 0\nINCR cma:books\nINCR cma:books\nGET cma:books', 'The final value is 2.', 'INCR expects an integer value. A key holding a word cannot be incremented as a number.', 'Add one more INCR and predict the value.', 'What does INCR add?', 'One', 'The key name length'),
 L('Give a key an expiry', 'An expiry makes a key disappear after a time limit. It is useful for temporary data such as a short-lived cached answer.', 'text', 'SET cma:tip "Water the plants" EX 30\nTTL cma:tip', 'TTL reports the remaining life in seconds, near 30 if checked immediately.', 'TTL changes with time. A missing key returns -2, so do not expect one fixed number after waiting.', 'Wait briefly and compare the remaining time.', 'What does EX 30 mean?', 'Expire the key after 30 seconds', 'Store exactly 30 characters'),
 L('Check whether a key exists', 'EXISTS checks for a key without reading its value. DEL removes the named key.', 'text', 'SET cma:temporary "sample"\nEXISTS cma:temporary\nDEL cma:temporary\nEXISTS cma:temporary', 'The first existence check returns 1, and the final check returns 0.', 'Delete only the intended practice key. Broad cleanup commands can remove unrelated data.', 'Explain why the last existence check is zero.', 'What does DEL remove here?', 'The named cma:temporary key', 'Every key on every server'),
 L('Group fields in a hash', 'A hash stores several named fields under one Redis key. It can hold a small record such as a book title and page count.', 'text', 'HSET cma:book:1 title "Moon Trip" pages 60\nHGET cma:book:1 title', 'The field lookup returns Moon Trip.', 'A hash field is inside a key. HGET needs both the key and field name.', 'Read the pages field from the same hash.', 'Which two names does HGET use?', 'The key and the field', 'The username and screen width'),
 L('Use a list as a small queue', 'A Redis list keeps values in order. Adding on the right and removing on the left gives first-in, first-out behaviour.', 'text', 'DEL cma:queue\nRPUSH cma:queue "Moon Trip" "Garden Days"\nLPOP cma:queue', 'The removed value is Moon Trip, the first item added.', 'This simple pop queue can lose a job if a worker fails after taking it. Reliable job systems need more design.', 'Pop the next item and predict its value.', 'Which item leaves this queue first?', 'Moon Trip', 'Garden Days'),
 L('Keep each member once', 'A set holds unique members without a promised order. Adding a duplicate does not make another copy.', 'text', 'DEL cma:readers\nSADD cma:readers Mia Sam Mia\nSCARD cma:readers', 'The set has 2 unique members.', 'Do not rely on the order returned by set member listings. Sets are about membership, not sequence.', 'Add one new name and one duplicate name.', 'What does SCARD count?', 'Unique members in the set', 'Every repeated add attempt'),
 L('Rank values with a sorted set', 'A sorted set pairs each member with a score. Redis can return members ordered by that score.', 'text', 'DEL cma:scores\nZADD cma:scores 5 Mia 8 Sam 3 Ravi\nZRANGE cma:scores 0 -1 WITHSCORES', 'The ascending order is Ravi with 3, Mia with 5, then Sam with 8.', 'A sorted-set score is a number used for ordering. The member name is still unique within the set.', 'Change Mia\'s score and inspect the new order.', 'What decides the sorted order here?', 'The numeric scores', 'Only the length of each name'),
 L('Scan keys in small batches', 'SCAN walks through key names using a cursor. It is safer for large keyspaces than asking for every matching key in one blocking command.', 'text', 'SCAN 0 MATCH cma:* COUNT 10', 'The response includes a next cursor and some matching keys. Continue with that cursor until it returns 0.', 'COUNT is a hint, not an exact batch size. A changing keyspace can produce duplicates, so callers must account for that.', 'Identify the cursor in a sample SCAN response.', 'When is a full SCAN iteration finished?', 'When the returned cursor is 0', 'After exactly ten keys every time'),
 L('Group commands with MULTI', 'MULTI queues commands for EXEC. Redis runs that queued group without another client\'s commands between them.', 'text', 'MULTI\nSET cma:points 2\nINCR cma:points\nEXEC', 'EXEC returns the results of setting the value and incrementing it to 3.', 'Redis transactions do not provide SQL-style rollback of commands that fail during execution. Validate the operations you queue.', 'Explain the final value after EXEC.', 'Does MULTI provide ordinary SQL-style rollback?', 'No, its transaction rules are different', 'Yes, every runtime error undoes all commands'),
 L('Publish a live message', 'Publish/subscribe sends live messages to clients currently listening to a channel. It is not a stored message history.', 'text', '# Terminal A:\nSUBSCRIBE cma:club-news\n# Terminal B:\nPUBLISH cma:club-news "Meeting at four"', 'The subscribed terminal receives Meeting at four while it is connected.', 'A subscriber that is offline misses messages. Use a durable design such as streams when replay is needed.', 'Send a second sample message from terminal B.', 'Will a late subscriber receive an old pub/sub message?', 'No, plain pub/sub has no replay history', 'Yes, every message is saved forever'),
 L('Choose what must survive a restart', 'Redis persistence settings decide how data is written to disk. A cache may be rebuildable, while important records need a deliberate durability plan.', 'text', 'Example decision:\nCached book summary: can be loaded again if lost.\nOnly copy of a payment record: must not depend on an unreviewed cache setup.\nCheck the server\'s RDB snapshot and AOF settings, then test a practice restart.', 'The worked decision separates replaceable cache data from records that need stronger guarantees.', 'Do not assume in-memory speed means guaranteed persistence. Backups and restore tests are separate jobs.', 'Classify a temporary reading-tip key as replaceable or essential.', 'What determines restart durability?', 'The configured persistence and backup design', 'Using a longer key name'),
])

build('sql-server',
 'SQL Server is Microsoft\'s table database. Its SQL form is called T-SQL. Learn named values, small tables and queries, then meet safe conversions, numbered results and transactions using sample records.',
 'Use SQL Server 2019+ in a separate practice database with a SQL editor. T-SQL is different from the SQLite engine on this site, so these examples are for that separate tool.',
 'Uses SQL Server 2019+ T-SQL, table variables and core query features.', [
 L('Calculate a named answer', 'T-SQL SELECT can return a calculation. AS gives the output column a name that explains the answer.', 'sql', 'SELECT 3 + 4 AS total_books;', 'The query returns total_books equal to 7.', 'Run this in SQL Server tooling. The course teaches the database; it does not add a database connection to this website.', 'Change the values and predict the new total.', 'What does AS name?', 'The output column', 'The database server password', slug='introduction'),
 L('Keep a local variable', 'A T-SQL variable starts with @. DECLARE gives it a type and an optional starting value.', 'sql', "DECLARE @name nvarchar(40)=N'Mia';\nSELECT N'Hello, '+@name AS greeting;", 'The result is Hello, Mia. N marks a Unicode string literal.', 'Choose a text length that fits the intended value. A variable exists only in its batch or procedure scope.', 'Change the variable to another sample name.', 'What starts a T-SQL variable name?', '@', '$'),
 L('Make a table variable', 'A table variable holds a small set of rows inside a batch. It can help you practise a query without creating a permanent table.', 'sql', "DECLARE @books table(id int,title nvarchar(80));\nINSERT INTO @books VALUES(1,N'Moon Trip'),(2,N'Garden Days');\nSELECT title FROM @books ORDER BY id;", 'The two titles appear in id order.', 'A table variable is not a persistent app database. Its scope ends with the batch.', 'Add a third row before the SELECT.', 'How long does this table variable last?', 'For its batch or procedure scope', 'Forever across every connection'),
 L('Choose top rows with a clear order', 'TOP limits the returned rows. ORDER BY tells SQL Server which rows count as first.', 'sql', "DECLARE @books table(title nvarchar(80),pages int);\nINSERT INTO @books VALUES(N'Moon Trip',60),(N'Tiny Seed',20);\nSELECT TOP (1) title FROM @books ORDER BY pages,title;", 'Tiny Seed is returned because it has fewer pages.', 'TOP without a meaningful ORDER BY does not mean the smallest or earliest row.', 'Return the longest book instead.', 'Why is Tiny Seed chosen?', 'The query sorts by pages before taking one row', 'Its name is always first in every table'),
 L('Filter rows with two rules', 'WHERE can combine tests with AND. A row must pass both tests to be included.', 'sql', "DECLARE @books table(title nvarchar(80),pages int,kind nvarchar(20));\nINSERT INTO @books VALUES(N'Moon Trip',60,N'story'),(N'Garden Facts',40,N'science');\nSELECT title FROM @books WHERE pages>=50 AND kind=N'story';", 'Only Moon Trip passes both rules.', 'Use parentheses when mixing AND and OR so the intended grouping is clear.', 'Change the minimum page count to 70.', 'What does AND require?', 'Both rules must be true', 'At least one rule may be ignored'),
 L('Summarise groups', 'GROUP BY collects rows with the same category. SUM adds a number for each group.', 'sql', "DECLARE @reading table(team nvarchar(20),books int);\nINSERT INTO @reading VALUES(N'Blue',2),(N'Blue',3),(N'Green',4);\nSELECT team,SUM(books) AS total FROM @reading GROUP BY team ORDER BY team;", 'Blue totals 5 books, and Green totals 4.', 'SUM adds values; COUNT counts rows. Choose the function that answers your question.', 'Add another Green row with two books.', 'Which function adds the books values?', 'SUM', 'COUNT(*) for the same meaning'),
 L('Read related tables', 'A join matches rows by keys. The relationship should be explicit instead of relying on row order.', 'sql', "DECLARE @authors table(id int,name nvarchar(40));\nDECLARE @books table(title nvarchar(80),author_id int);\nINSERT INTO @authors VALUES(1,N'Mia');\nINSERT INTO @books VALUES(N'Moon Trip',1);\nSELECT b.title,a.name FROM @books AS b JOIN @authors AS a ON a.id=b.author_id;", 'The result joins Moon Trip with author Mia.', 'A wrong join condition can duplicate or lose the intended pairings.', 'Add another author and matching book.', 'What matches the book to its author?', 'The author id values', 'The order of insert statements only'),
 L('Handle a conversion that may fail', 'TRY_CAST attempts a type conversion. It returns NULL when an ordinary conversion fails, so code can handle the missing result.', 'sql', "SELECT TRY_CAST(N'12' AS int) AS good_value,\n       TRY_CAST(N'twelve' AS int) AS missing_value;", 'The first value is 12 and the second is NULL.', 'NULL is not zero. Check for it before using a failed conversion in important calculations.', 'Try converting a different text number.', 'What does TRY_CAST return for this invalid numeric text?', 'NULL', 'The number zero automatically'),
 L('Number a sorted result', 'ROW_NUMBER assigns a sequence based on its window order. The original rows remain separate.', 'sql', "DECLARE @books table(title nvarchar(80),pages int);\nINSERT INTO @books VALUES(N'Moon Trip',60),(N'Tiny Seed',20);\nSELECT title,ROW_NUMBER() OVER(ORDER BY pages,title) AS place FROM @books ORDER BY place;", 'Tiny Seed is numbered 1, and Moon Trip is numbered 2.', 'Use enough ordering fields to break ties if a stable numbering is needed.', 'Reverse the page order and predict the numbers.', 'Does ROW_NUMBER keep each original row?', 'Yes, it adds a number to each row', 'No, it merges all rows into one'),
 L('Undo a sample transaction', 'A transaction can keep related changes together. ROLLBACK cancels changes made within it to a normal temporary table.', 'sql', 'DROP TABLE IF EXISTS #practice_scores;\nCREATE TABLE #practice_scores(points int);\nBEGIN TRANSACTION;\nINSERT INTO #practice_scores VALUES(5);\nROLLBACK TRANSACTION;\nSELECT COUNT(*) AS rows_left FROM #practice_scores;', 'The temporary table remains, but rows_left is 0 because the insert was rolled back.', 'Table variables have different rollback behaviour. This example deliberately uses a # temporary table.', 'Explain why the table was created before BEGIN TRANSACTION.', 'Which object is used for this rollback example?', 'A # temporary table', 'A table variable with identical rollback rules'),
 L('Pass a query parameter', 'A parameter keeps a data value separate from the SQL command text. It avoids building the command by joining input strings.', 'sql', "DECLARE @wanted int=4;\nEXEC sys.sp_executesql\n N'SELECT @number + 1 AS next_number;',\n N'@number int',\n @number=@wanted;", 'The parameter value 4 produces next_number equal to 5.', 'Do not join untrusted text into dynamic SQL. Parameters represent values, not arbitrary table names.', 'Change the wanted value and predict the answer.', 'Why use a parameter?', 'To pass a value separately from command text', 'To turn all user input into SQL code'),
 L('Let an identity column make an id', 'An IDENTITY column generates numeric values for new rows. OUTPUT can show the id that was actually inserted.', 'sql', 'DROP TABLE IF EXISTS #new_books;\nCREATE TABLE #new_books(id int IDENTITY(1,1) PRIMARY KEY,title nvarchar(80));\nINSERT INTO #new_books(title) OUTPUT inserted.id,inserted.title VALUES(N\'Moon Trip\');', 'The inserted sample row is returned with its generated id and title.', 'Do not assume identity values are gap-free. Failed or removed rows can leave gaps.', 'Insert a second book and read the returned id.', 'What should an app use for a new row\'s id?', 'The id returned by the insert', 'A guess based on the current row count'),
])

build('oracle-database',
 'Oracle Database stores data in tables and includes the PL/SQL programming language. Learn clear queries, dates, row rules and a small block of PL/SQL with sample book information.',
 'Use Oracle Database 19c+ with a SQL editor in a new practice schema. Oracle SQL and PL/SQL do not run in this site\'s SQLite playground. Create only the named sample objects in that practice schema.',
 'Uses Oracle 19c+ SQL, DUAL, identity columns and basic PL/SQL.', [
 L('Ask DUAL for a calculation', 'DUAL is a small built-in table used when a query needs no real table data. It is handy for trying a calculation.', 'sql', 'SELECT 2 + 3 AS total_books FROM dual;', 'The answer is one row with total_books equal to 5.', 'These examples keep FROM dual for compatibility with the stated Oracle version.', 'Change the two numbers and calculate the result.', 'Why use DUAL here?', 'The calculation needs no application table', 'It creates two copies of every row', slug='introduction'),
 L('Choose number and text types', 'Oracle types describe the values a column or expression holds. NUMBER stores numbers, and VARCHAR2 stores variable-length text.', 'sql', "SELECT CAST(12 AS NUMBER(3)) AS pages, CAST('Moon Trip' AS VARCHAR2(40)) AS title FROM dual;", 'The row contains the number 12 and text Moon Trip.', 'Choose lengths and precision that fit the data. A type is a rule, not just a label for display.', 'Cast another short title as VARCHAR2(40).', 'Which type is used for the text title?', 'VARCHAR2', 'NUMBER'),
 L('Build a small query-only list', 'A WITH query gives a temporary name to a result used by that statement. UNION ALL keeps every supplied row.', 'sql', "WITH books(title,pages) AS (SELECT 'Moon Trip',60 FROM dual UNION ALL SELECT 'Tiny Seed',20 FROM dual)\nSELECT title,pages FROM books ORDER BY pages;", 'Tiny Seed appears before Moon Trip in page-count order.', 'This WITH result exists only for this statement. It does not create a saved table.', 'Add a third SELECT row to the WITH list.', 'How long does this named WITH result last?', 'For this query', 'Permanently as a new schema'),
 L('Fetch the first sorted row', 'FETCH FIRST limits rows after the chosen order. It can answer questions such as which sample book is shortest.', 'sql', "WITH books(title,pages) AS (SELECT 'Moon Trip',60 FROM dual UNION ALL SELECT 'Tiny Seed',20 FROM dual)\nSELECT title FROM books ORDER BY pages,title FETCH FIRST 1 ROW ONLY;", 'The result is Tiny Seed.', 'Use ORDER BY when the word first has a meaningful rule. Row storage order is not that rule.', 'Return the longest book instead.', 'What makes the first row the shortest book?', 'ORDER BY pages before the row limit', 'The position of the file on disk'),
 L('Write an unambiguous date', 'A DATE literal names a calendar date in a fixed form. TO_CHAR can choose a clear display format for it.', 'sql', "SELECT TO_CHAR(DATE '2026-11-16','YYYY-MM-DD') AS club_day FROM dual;", 'The displayed club_day is 2026-11-16.', 'Do not rely on a machine\'s default date format when a string could mean different dates.', 'Write a date literal for the next club meeting.', 'Why use the DATE literal form?', 'To avoid an ambiguous text date format', 'To save the local timezone automatically'),
 L('Handle a missing value', 'NULL means a value is missing or unknown. NVL can supply another value when its first input is NULL.', 'sql', "SELECT NVL(CAST(NULL AS VARCHAR2(20)),'Not chosen') AS book_choice FROM dual;", 'The result is Not chosen.', 'Test missing values with IS NULL, not = NULL. Missing is not the same as an ordinary empty label.', 'Choose a different fallback message.', 'What does NVL use when the first value is NULL?', 'Its second value', 'Always the number zero'),
 L('Join a book and its author', 'A join combines records whose key values match. It lets related facts stay in separate tables or query results.', 'sql', "WITH authors(id,name) AS (SELECT 1,'Mia' FROM dual), books(title,author_id) AS (SELECT 'Moon Trip',1 FROM dual)\nSELECT b.title,a.name FROM books b JOIN authors a ON a.id=b.author_id;", 'Moon Trip is paired with Mia.', 'Oracle table aliases in this syntax are written without AS. Keep dialect differences in mind.', 'Add a second author and book to the sample.', 'What is the join rule?', 'The author id values are equal', 'Both values have the same text length'),
 L('Count a category', 'GROUP BY makes one result per category. COUNT counts rows belonging to that category.', 'sql', "WITH books(kind) AS (SELECT 'story' FROM dual UNION ALL SELECT 'story' FROM dual UNION ALL SELECT 'science' FROM dual)\nSELECT kind,COUNT(*) AS total FROM books GROUP BY kind ORDER BY kind;", 'Science has 1 row and story has 2.', 'COUNT(column) ignores NULL in that column. COUNT(*) counts rows.', 'Add another science row and predict its count.', 'What does COUNT(*) count?', 'All rows in each group', 'Only non-empty characters'),
 L('Create an identity key', 'An identity column lets Oracle create a numeric id. A primary key makes that id unique and required.', 'sql', 'CREATE TABLE cma_oracle_books (id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,title VARCHAR2(80) NOT NULL);\nINSERT INTO cma_oracle_books(title) VALUES(\'Moon Trip\');\nSELECT id,title FROM cma_oracle_books;', 'The new practice table contains a generated id and the title Moon Trip.', 'Run CREATE TABLE once in a new practice schema. Oracle DDL can commit transactions, so do not mix it carelessly with undo experiments.', 'Explain which rule requires a title.', 'What creates the numeric id automatically?', 'The identity column', 'The title length'),
 L('Read a sequence value', 'A sequence is a separate object that gives out numbers. NEXTVAL asks for its next value.', 'sql', 'CREATE SEQUENCE cma_book_numbers START WITH 100 INCREMENT BY 1;\nSELECT cma_book_numbers.NEXTVAL AS number_value FROM dual;', 'The first NEXTVAL is 100 in this newly created sequence.', 'Sequence numbers are not gap-free and are not rolled back like ordinary row changes.', 'Ask for the next sequence value once more.', 'Does rolling back a row insert guarantee sequence numbers are reused?', 'No, sequence values can leave gaps', 'Yes, sequences always reuse them'),
 L('Run a small PL/SQL block', 'PL/SQL adds variables and step-by-step instructions to Oracle SQL. A block can declare a value and use it in a statement.', 'sql', "DECLARE\n  books NUMBER := 3;\nBEGIN\n  DBMS_OUTPUT.PUT_LINE('Books: ' || books);\nEND;\n/", 'With DBMS Output enabled in the client, the block prints Books: 3.', 'Enable the client\'s DBMS Output display. The slash is a client command used by tools such as SQL*Plus, not part of the PL/SQL block itself.', 'Change books to 5 and predict the line.', 'Which procedure writes this demonstration output?', 'DBMS_OUTPUT.PUT_LINE', 'SELECT ALL PASSWORDS'),
 L('Undo uncommitted sample changes', 'A savepoint marks a point inside a transaction. ROLLBACK TO can undo later changes while keeping earlier work in that transaction.', 'sql', "-- After creating cma_oracle_books; finish any earlier practice transaction first.\nSAVEPOINT before_extra;\nINSERT INTO cma_oracle_books(title) VALUES('Temporary sample');\nROLLBACK TO before_extra;\nSELECT title FROM cma_oracle_books WHERE title='Temporary sample';", 'The extra sample title is not returned after the rollback to the savepoint.', 'This demonstration assumes no earlier row has that title. Do not run DDL between the savepoint and rollback.', 'Explain which insert the savepoint rollback undoes.', 'What does ROLLBACK TO before_extra cancel?', 'Changes made after that savepoint', 'Every schema object ever created'),
])
